function pagePromessas(){
 const db=DATA.promessas||{}, ps=db.prefeito?.compromissos||[],vs=db.vereadores?.registros||[];
 const cats=[...new Set(ps.map(x=>x.tema))],matched=ps.filter(x=>x.evidencias?.length).length,planned=ps.filter(x=>x.ppa_2026_2029?.length).length;
 const statusOrder=['Promessa registrada','Em planejamento','Em andamento','Parcialmente realizada','Realizada','Sem dados suficientes'];
 const statusCounts=Object.fromEntries(statusOrder.map(st=>[st,ps.filter(x=>x.situacao_acompanhamento===st).length]));
 const statusClass=st=>({'Promessa registrada':'registered','Em planejamento':'planned','Em andamento':'ongoing','Parcialmente realizada':'partial','Realizada':'done','Sem dados suficientes':'pending'}[st]||'pending');
 app.innerHTML=pageHero('Eleições municipais • 2024', 'Promessas e <em>resultados documentados.</em>', 'O que o prefeito propôs para o mandato 2025–2028 e quais documentos posteriores conseguimos relacionar a cada compromisso. Sem notas, rankings ou conclusão por ausência de registro.')+`
 <section class="page-section promise-page">
  ${prefeitoCard()}
 <div class="promise-summary"><div><small>COMPROMISSOS CATALOGADOS</small><strong>${fmt(ps.length)}</strong><span>Unidades editoriais de leitura do plano de 13 páginas, não contagem oficial de promessas</span></div><div><small>ÁREAS DO PROGRAMA</small><strong>${fmt(cats.length)}</strong><span>Saúde, educação, mobilidade e outras políticas</span></div><div><small>ITENS COM FONTE POSTERIOR ASSOCIADA</small><strong>${fmt(matched)}</strong><span>Referência documental não comprova entrega</span></div></div>
 <div class="promise-status-overview" aria-label="Filtrar compromissos por estágio documental">${statusOrder.map(st=>`<button type="button" class="promise-stage promise-stage-${statusClass(st)}" data-stage="${esc(st)}" aria-pressed="false" aria-label="Ver ${fmt(statusCounts[st])} compromissos classificados como ${esc(st)}"><small>${esc(st)}</small><strong>${fmt(statusCounts[st])}</strong><span>${st==='Promessa registrada'?'Somente o compromisso eleitoral foi registrado nesta revisão':st==='Em planejamento'?'Planejamento específico ou obra correlata cadastrada; sem entrega comprovada':st==='Sem dados suficientes'?'Fontes indiretas ainda não definem o estágio':st==='Em andamento'?'Execução material comprovada com fonte':st==='Parcialmente realizada'?'Entrega parcial e mensurável comprovada':'Entrega correspondente ao compromisso comprovada'}</span></div>`).join('')}</div>
 <div class="ppa-overview"><div><span class="eyebrow">PLANEJAMENTO MUNICIPAL • 2026–2029</span><h2>Da promessa ao PPA — e do PPA à execução</h2><p><strong>${fmt(planned)} compromissos</strong> têm uma ação ou programa relacionado localizado no PPA. Essas são <strong>relações documentais de diferentes graus</strong>; nem todas comprovam planejamento específico da promessa e nenhuma comprova sua entrega.</p><p>As correspondências são documentadas, individualizadas e sujeitas a revisão. Outros compromissos ainda não foram relacionados — o que não indica que estejam fora do orçamento.</p><div class="promise-links">${ext(db.ppa_documento?.fonte_anexo,'Anexo III oficial do PPA 2026–2029 ↗')}${ext(db.ppa_documento?.fonte_indice,'Página de anexos no SAPL ↗')}</div></div><div class="ppa-steps"><span><b>1</b> Promessa eleitoral</span><span><b>2</b> Meta ou ação prevista</span><span><b>3</b> Empenho / contrato / execução</span><span><b>4</b> Entrega comprovada</span><small>Etapas 3 e 4 exigem documentação própria; não são inferidas do PPA.</small></div></div>
 <div class="attention-card"><h2>O que estes números significam?</h2><p><strong>Revisão de ${date(db.data_revisao)}:</strong> as categorias mostram somente o grau de verificação documental realizado pelo projeto até essa data. Não representam percentual de promessas cumpridas ou descumpridas. Um compromisso sem avanço identificado pode ter ações ainda não incorporadas à nossa base.</p><p><a href="documentos/compromissos_status_2024.csv" download>Baixar a classificação completa, com fontes e ressalvas (CSV) ↓</a></p></div><div class="attention-card"><h2>Como ler este levantamento</h2><p>O plano foi apresentado para a eleição de 2024. Cada compromisso abaixo foi resumido, sem atribuir uma nota ao governo. <strong>“Promessa registrada” não significa descumprimento, e “Sem dados suficientes” indica vínculo documental inconclusivo.</strong> Um cadastro de obra, uma verba planejada ou uma indicação legislativa não comprovam que uma promessa foi cumprida.</p><p>${ext(db.fonte_primaria?.url||'https://divulgacandcontas.tse.jus.br/','Consultar plano eleitoral integral (13 páginas) ↗')}</p></div>
 <div class="promise-tabs" role="group" aria-label="Tipo de fonte"><button type="button" class="promise-tab is-on" data-promise-tab="executivo">Prefeito — plano de 2024</button><button type="button" class="promise-tab" data-promise-tab="legislativo">Vereadores — posições registradas</button></div>
 <div id="promise-exec"><div class="promise-filters"><label>Área do plano<select id="promessa-tema"><option value="">Todas as áreas</option>${cats.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')}</select></label><label>Buscar compromisso<input id="promessa-busca" type="search" placeholder="Ex.: Contorno Sul, saúde, creche"></label><label>Situação documental<select id="promessa-estado"><option value="">Todas as situações</option>${statusOrder.map(st=>`<option value="${esc(st)}">${esc(st)} (${statusCounts[st]})</option>`).join('')}</select></label></div><div id="promise-results"></div></div>
 <div id="promise-legis" hidden><div class="attention-card"><h2>O que sabemos sobre as propostas dos vereadores?</h2><p>Não há plano de governo obrigatório e uniforme para cada candidatura a vereador. Os registros abaixo são <strong>prioridades descritas pela própria Câmara em fevereiro de 2025, após a eleição</strong>, e não devem ser apresentados como promessas específicas feitas na campanha de 2024. Não demonstram projeto aprovado nem resultado obtido.</p><p>${ext(db.vereadores?.fonte||'https://www.cmm.pr.gov.br/','Conferir a publicação institucional de 02/02/2025 ↗')}</p></div><div class="promise-people">${vs.map(v=>{const pp=DATA.people.find(p=>norm(p.nome).includes(norm(v.nome))||norm(v.nome).includes(norm(p.nome)));return `<article class="promise-item"><span class="promise-label">POSIÇÕES INSTITUCIONAIS • 2025</span><h3>${esc(v.nome)}</h3><p>${esc(v.tema)}</p><small>${esc(v.natureza)}</small><div class="promise-links">${pp?`<a href="${personLink(pp)}">Consultar matérias do parlamentar →</a>`:''}${ext(v.fonte,'Ver publicação da Câmara ↗')}</div></article>`}).join('')}</div><div class="attention-card"><h2>Compromissos eleitorais individuais</h2><p>Materiais de campanha de 2024 exigem identificação do autor, data e cópia verificável. Não atribuímos uma promessa ao vereador com base em suas matérias de 2026 nem em uma biografia escrita depois da eleição. Os demais parlamentares permanecem sem registro de campanha individual verificado nesta edição.</p></div></div>
 <div class="attention-card"><h2>Documentos para acompanhamento independente</h2><div class="promise-links">${(db.fontes_complementares||[]).map(x=>ext(x.url,esc(x.titulo)+' ↗')).join('')}</div><p class="editorial-note">Data da organização: ${date(db.data_revisao)}. O acompanhamento não é auditoria oficial. Se uma proposta não possui evidência ligada nesta versão, isso não prova descumprimento. <a href="#metodologia">Metodologia geral →</a></p></div>
 </section>`;
 const a=document.querySelector('#promise-results'); const ftema=document.querySelector('#promessa-tema'),busca=document.querySelector('#promessa-busca'),estate=document.querySelector('#promessa-estado');
 function draw(){let records=ps.filter(x=>(!ftema.value||x.tema===ftema.value)&&(!busca.value||norm(x.compromisso+' '+x.tema).includes(norm(busca.value)))&&(!estate.value||x.situacao_acompanhamento===estate.value));
 a.innerHTML=`<p class="result-count">${records.length} compromisso(s) neste recorte. Ordem do programa temático, não classificação política.</p><div class="promise-list">${records.map(x=>`<article class="promise-item"><div class="promise-item-top"><span class="promise-label">${esc(x.tema)} • PÁG. ${x.pagina_pdf} DO PDF</span><span class="promise-status promise-status-${statusClass(x.situacao_acompanhamento)}">${esc(x.situacao_acompanhamento)}</span></div><h3>${esc(x.compromisso)}</h3><p><strong>Por que esta situação?</strong> ${esc(x.fundamentacao_situacao)}</p><p class="promise-evidence-note">${esc(x.nivel_evidencia)} · Revisão em ${date(x.revisado_em)}</p>${x.evidencias?.length?`<div class="promise-evidence"><strong>Documento(s) localizado(s)</strong>${x.evidencias.map(e=>`<p>${ext(e.url,esc(e.titulo)+' ↗')}<br><small>${esc(e.observacao)}</small></p>`).join('')}</div>`:''}${x.ppa_2026_2029?.length?`<div class="ppa-links"><strong>Ação/programa previsto no PPA 2026–2029</strong><p class="small-p">Planejamento não equivale a gasto realizado nem a promessa cumprida.</p>${x.ppa_2026_2029.map(q=>`<div class="ppa-action"><span>${esc(q.codigo)} • ${esc(q.programa)} • pág. ${q.pagina_pdf}</span><b>${esc(q.acao)}</b>${q.meta_2026?`<small>Meta planejada para 2026: ${esc(q.meta_2026)}${q.valor_previsto_2026?' • previsão: '+money(q.valor_previsto_2026*100):''}</small>`:''}<p>${esc(q.ressalva)}</p></div>`).join('')}<div class="promise-links">${ext(db.ppa_documento.fonte_anexo,'Ver PPA oficial ↗')}</div></div>`:''}<div class="promise-links">${ext(x.fonte_plano,`Ler plano de 2024 (página ${x.pagina_pdf}) ↗`)}</div></article>`).join('')}</div>`;}
 ftema.onchange=draw;busca.oninput=draw;
 function updateStageButtons(){document.querySelectorAll('[data-stage]').forEach(b=>{const selected=estate.value===b.dataset.stage;b.classList.toggle('is-selected',selected);b.setAttribute('aria-pressed',String(selected))})}
 estate.onchange=()=>{updateStageButtons();draw()};
 document.querySelectorAll('[data-stage]').forEach(b=>b.addEventListener('click',()=>{estate.value=estate.value===b.dataset.stage?'':b.dataset.stage;updateStageButtons();draw();document.querySelector('#promise-results').scrollIntoView({behavior:'smooth',block:'start'})}));
 updateStageButtons();draw();
 document.querySelectorAll('[data-promise-tab]').forEach(b=>b.onclick=()=>{const legislative=b.dataset.promiseTab==='legislativo';document.querySelector('#promise-exec').hidden=legislative;document.querySelector('#promise-legis').hidden=!legislative;document.querySelectorAll('[data-promise-tab]').forEach(t=>{t.classList.toggle('is-on',t===b);t.setAttribute('aria-pressed',String(t===b))})});
}

function route(){const [part,param]=parseRoute();document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.nav===(['bairro'].includes(part)?'bairros':['vereador'].includes(part)?'vereadores':['materia','tema'].includes(part)?'pautas':part)));viewLimit=24;switch(part){case 'inicio':homepage();break;case 'dinheiro':pageDinheiro();break;case 'pagamentos':pagePagamentos();break;case 'execucao':pageExecucao();break;case 'fornecedores':pageFornecedores();break;case 'investigacoes':pageInvestigacoes();break;case 'evidencias':pageCentralEvidencias();break;case 'auditoria':pageAuditoriaPublicacao();break;case 'investigacao':pageInvestigacao(param);break;case 'empresa':pageEmpresa(param);break;case 'contratos':pageContratosFinance();break;case 'licitacoes':pageLicitacoesFinance();break;case 'diarias':pageDiariasFinance();break;case 'publicidade':pagePublicidade();break;case 'obras':pageObras();break;case 'prefeitura':pagePrefeitura();break;case 'promessas':pagePromessas();break;case 'acompanhamento':pageAcompanhamento();break;case 'bairros':pageBairros('');break;case 'bairro':pageBairros(param);break;case 'vereadores':pageVereadores();break;case 'vereador':pageVereador(param);break;case 'pautas':pagePautas();break;case 'tema':themePage(param);break;case 'materia':pageMateria(param);break;case 'sessoes':pageSessoes();break;case 'atualizacoes':pageAtualizacoes();break;case 'metodologia':pageMetodo();break;default:homepage()}window.scrollTo({top:0,behavior:'instant'});const nav=document.querySelector('#navigation');nav.classList.remove('open');nav.querySelectorAll('details').forEach(d=>{d.open=false;d.classList.toggle('has-active',!!d.querySelector('a.active'))});document.querySelector('#menu-btn').setAttribute('aria-expanded','false')}
async function init(){try{const files=['materias.json','parlamentares.json','sessoes.json','metadados.json','financas_apuradas.json','transparencia_exemplos.json','execucao_2026.json','dossies_fornecedores_2026.json','fotos_vereadores.json','conferencia_contratos_2026.json','analise_beneficiarios_2026.json','investigacoes_documentadas_2026.json','central_evidencias_2026.json','auditoria_publicacao_2026.json','prefeitura_2026.json','remuneracao_vereadores_2026.json','promessas_2024.json'];const results=await Promise.all(files.map(async f=>{const r=await fetch('dados/'+f);if(!r.ok)throw Error('Não foi possível acessar '+f);return r.json()}));[DATA.matters,DATA.people,DATA.sessions,DATA.meta,DATA.finance,DATA.exemplos,DATA.execucao,DATA.dossies,DATA.fotos,DATA.conferencia,DATA.insights,DATA.investigacoes,DATA.central,DATA.auditoria,DATA.prefeitura,DATA.remuneracao,DATA.promessas]=results;DATA.matById=new Map(DATA.matters.map(m=>[m.id,m]));document.querySelector('#ticker-date').textContent='Corte: '+date(DATA.meta.data_corte);document.querySelector('#foot-cut').textContent='Base: '+fmt(DATA.matters.length)+' matérias até '+date(DATA.meta.data_corte);document.querySelector('#ticker-txt').textContent=`${fmt(DATA.matters.length)} matérias de 2026 analisadas • ${fmt(ind().length)} indicações • Dados da Câmara Municipal`;route();window.addEventListener('hashchange',route);}catch(err){app.innerHTML=`<div class="empty"><h2>Não foi possível carregar a base</h2><p>${esc(err.message)}</p><p>Para usar o site, abra <strong>INICIAR-SITE.bat</strong> na pasta principal e acesse <strong>http://localhost:8000</strong>. Abrir o HTML diretamente pode impedir a leitura dos arquivos JSON.</p></div>`;console.error(err)}}
document.querySelector('#menu-btn').onclick=()=>{const nav=document.querySelector('#navigation');const open=nav.classList.toggle('open');document.querySelector('#menu-btn').setAttribute('aria-expanded',String(open));if(!open)nav.querySelectorAll('details').forEach(d=>d.open=false)};
// Somente um submenu aberto; escape e clique fora fecham os painéis.
document.querySelectorAll('#navigation details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)document.querySelectorAll('#navigation details').forEach(other=>{if(other!==d)other.open=false})}));
document.addEventListener('keydown',event=>{if(event.key==='Escape'){document.querySelectorAll('#navigation details').forEach(d=>d.open=false);document.querySelector('#navigation').classList.remove('open');document.querySelector('#menu-btn').setAttribute('aria-expanded','false')}});
document.addEventListener('click',event=>{if(!event.target.closest('.site-head')){document.querySelectorAll('#navigation details').forEach(d=>d.open=false);document.querySelector('#navigation').classList.remove('open');document.querySelector('#menu-btn').setAttribute('aria-expanded','false')}});
init();
